  "test": "from types import SimpleNamespace
from typing import Any, Optional

import pytest

from langfuse._client.span_filter import (
    is_known_llm_instrumentor,
    is_default_export_span,
)


def _make_span(*, scope_name: Optional[str] = None, attributes: Optional[dict[Any, Any]] = None):
    scope = None if scope_name is None else SimpleNamespace(name=scope_name)
    return SimpleNamespace(instrumentation_scope=scope, attributes=attributes)


def test_is_known_llm_instrumentor_tiktoken():
    """Spans from the tiktoken library should be considered known LLm instrumentors after the change."""
    span = _make_span(scope_name="tiktoken")
    assert is_known_llm_instrumentor(span) is True


def test_is_default_export_span_tiktoken():
    """Spans from tiktoken should be exported by default after the change."""
    span = _make_span(scope_name="tiktoken")
    assert is_default_export_span(span) is True
